// Build the human-facing request from the TYPED contract (G3).
//
// The gate used to render `${i.title}` + a free-text message. A human cannot
// judge "APPROVAL NEEDED: action" — so they approve it, which is exactly the
// rubber-stamp Lanham's second HITL decision warns about. The router already
// computed every field below; this only has to show them.
const i = $input.first().json;
const url = $execution.resumeUrl;

// FAIL CLOSED on an incomplete request. Rendering a prompt with blanks asks a
// human to authorise something nobody described, and the old `|| 'action'`
// fallback made that the DEFAULT rather than an error. Throwing here means no
// approval is sent, which is the safe direction: nothing gets approved.
const required = ['action', 'scope', 'riskTier', 'requester', 'dataTouched', 'preview'];
const missing = required.filter((k) => i[k] === undefined || i[k] === null || i[k] === '');
if (missing.length) {
  throw new Error(
    `approval-gate: refusing to ask for approval without [${missing.join(', ')}]. ` +
    `An approval prompt a human cannot judge is worse than no gate — they approve it. ` +
    `The caller must map these; workflow_lint.py enforces it.`);
}

const row = (k, v) => `  ${String(k).padEnd(13)}${v}`;
const fired = i.dimensions ? `  (fired: ${i.dimensions})` : '';

const message = [
  `WHAT WILL HAPPEN IF YOU APPROVE`,
  `  ${i.action}`,
  ``,
  row('Scope', i.scope),
  row('Risk', `${i.riskTier}${fired}`),
  row('Requested by', i.requester),
  row('Data touched', i.dataTouched),
  ``,
  `PREVIEW`,
  String(i.preview).split('\n').map((l) => '  ' + l).join('\n'),
  ``,
  `✅ Approve: ${url}?approved=true`,
  `❌ Reject:  ${url}?approved=false`,
  ``,
  `No response within 24h = REJECTED. Rejecting costs a round trip;`,
  `approving something you could not verify costs whatever it does next.`,
].join('\n');

return [{ json: {
  severity: 'warn',
  title: `APPROVAL NEEDED: ${i.action}`,
  message,
  source: i.source || 'approval-gate',
} }];

// Resumed either by a clicked link (query.approved present) or by timeout.
// Anything other than an explicit approved=true is a rejection — default deny.
const q = $input.first().json.query || {};
const timedOut = q.approved === undefined;
return [{ json: {
  approved: q.approved === 'true',
  auto: false,
  timedOut
} }];
